This binary search sometimes never returns. Find the bug, explain it in one or two sentences, and give the corrected function.

```python
def find(xs, target):
    lo, hi = 0, len(xs) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < target:
            lo = mid
        else:
            hi = mid
    return lo if xs and xs[lo] == target else -1
```

Refactor this Node.js function to use async/await with `fs/promises` instead of callbacks. Keep the behaviour the same, including the error handling.

```js
const fs = require('fs');

function loadConfig(path, callback) {
  fs.readFile(path, 'utf8', (err, text) => {
    if (err) {
      if (err.code === 'ENOENT') return callback(null, {});
      return callback(err);
    }
    let config;
    try {
      config = JSON.parse(text);
    } catch (e) {
      return callback(new Error(`bad JSON in ${path}: ${e.message}`));
    }
    fs.stat(path, (err, st) => {
      if (err) return callback(err);
      config.loadedAt = st.mtime;
      callback(null, config);
    });
  });
}
```
